{"content":"/* =========================================================
   珈琲 灯里 — stylesheet
   ========================================================= */

/* ---------- tokens ---------- */
:root {
  --cream:      #f7f3ee;
  --cream-deep: #efe8df;
  --ink:        #241c16;
  --ink-soft:   #4d423a;
  --muted:      #857668;
  --line:       #e0d6ca;
  --espresso:   #2b2018;
  --amber:      #b9763f;
  --amber-soft: #d79a5b;
  --amber-tint: rgba(185, 118, 63, .1);

  --font-serif: "Zen Old Mincho", "Shippori Mincho", "Hiragino Mincho ProN", "Yu Mincho", serif;
  --font-sans:  "Inter", "Hiragino Sans", "Noto Sans JP", system-ui, -apple-system, "Helvetica Neue", sans-serif;

  --wrap: 1180px;
  --radius: 18px;
  --ease: cubic-bezier(.22, .61, .36, 1);
  --shadow-sm: 0 1px 2px rgba(43, 32, 24, .05);
  --shadow:    0 18px 40px -24px rgba(43, 32, 24, .35);
  --shadow-lg: 0 40px 80px -40px rgba(43, 32, 24, .45);

  --header-h: 76px;
}

/* ---------- reset ---------- */
*, *::before, *::after { box-sizing: border-box; }

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--cream);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.85;
  font-weight: 400;
  letter-spacing: .01em;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

h1, h2, h3, h4 { margin: 0; font-family: var(--font-serif); font-weight: 500; line-height: 1.35; letter-spacing: .01em; }
p { margin: 0; }
ul, ol, dl, dd { margin: 0; padding: 0; list-style: none; }
a { color: inherit; text-decoration: none; }
img, svg { display: block; max-width: 100%; }
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }

::selection { background: var(--amber); color: #fff; }

:focus-visible {
  outline: 2px solid var(--amber);
  outline-offset: 3px;
  border-radius: 4px;
}

.wrap {
  width: 100%;
  max-width: var(--wrap);
  margin-inline: auto;
  padding-inline: clamp(20px, 5vw, 48px);
}

.skip-link {
  position: absolute;
  left: 12px; top: -60px;
  z-index: 200;
  background: var(--espresso);
  color: #fff;
  padding: 10px 16px;
  border-radius: 8px;
  transition: top .2s var(--ease);
}
.skip-link:focus { top: 12px; }

/* ---------- typography helpers ---------- */
.eyebrow {
  font-size: 11px;
  font-weight: 500;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--amber);
}

/* ---------- buttons ---------- */
.btn {
  --btn-bg: var(--espresso);
  --btn-fg: var(--cream);
  display: inline-flex;
  align-items: center;
  gap: .55em;
  padding: 15px 30px;
  border-radius: 999px;
  background: var(--btn-bg);
  color: var(--btn-fg);
  font-size: 14px;
  font-weight: 500;
  letter-spacing: .04em;
  box-shadow: var(--shadow-sm);
  transition: transform .35s var(--ease), box-shadow .35s var(--ease), background .35s var(--ease);
  will-change: transform;
}
.btn:hover { transform: translateY(-2px); box-shadow: var(--shadow); background: #3a2c21; }
.btn:active { transform: translateY(0); }

.btn-ghost {
  --btn-bg: transparent;
  --btn-fg: var(--ink);
  border: 1px solid var(--line);
  padding-block: 14px;
}
.btn-ghost:hover { background: rgba(43, 32, 24, .04); border-color: var(--muted); }

.btn-sm { padding: 11px 22px; font-size: 13px; }

/* =========================================================
   HEADER
   ========================================================= */
.site-header {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 100;
  height: var(--header-h);
  display: flex;
  align-items: center;
  transition: background .4s var(--ease), box-shadow .4s var(--ease), border-color .4s var(--ease);
  border-bottom: 1px solid transparent;
}
.site-header.is-scrolled {
  background: rgba(247, 243, 238, .82);
  backdrop-filter: blur(14px) saturate(1.4);
  -webkit-backdrop-filter: blur(14px) saturate(1.4);
  border-bottom-color: var(--line);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  width: 100%;
}

.brand { display: flex; align-items: center; gap: 12px; }
.brand-mark svg { width: 34px; height: 34px; overflow: visible; }
.brand-mark svg path {
  fill: none;
  stroke: var(--espresso);
  stroke-width: 1.9;
  stroke-linecap: round;
}
.brand-mark-steam { opacity: .45; stroke: var(--amber) !important; }

.brand-text { display: flex; flex-direction: column; line-height: 1.15; }
.brand-name { font-family: var(--font-serif); font-size: 18px; letter-spacing: .12em; }
.brand-sub { font-size: 9px; letter-spacing: .28em; color: var(--muted); }

.nav { display: flex; align-items: center; gap: 34px; }
.nav ul { display: flex; gap: 30px; }
.nav a:not(.btn) {
  position: relative;
  font-size: 13.5px;
  letter-spacing: .06em;
  color: var(--ink-soft);
  padding-block: 6px;
  transition: color .3s var(--ease);
}
.nav a:not(.btn)::after {
  content: "";
  position: absolute;
  left: 0; bottom: 0;
  width: 100%; height: 1px;
  background: var(--amber);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform .4s var(--ease);
}
.nav a:not(.btn):hover { color: var(--ink); }
.nav a:not(.btn):hover::after { transform: scaleX(1); }

.nav-toggle {
  display: none;
  width: 44px; height: 44px;
  position: relative;
  border-radius: 50%;
}
.nav-toggle span {
  position: absolute;
  left: 12px; right: 12px;
  height: 1.6px;
  background: var(--espresso);
  transition: transform .35s var(--ease), opacity .25s var(--ease), top .35s var(--ease);
}
.nav-toggle span:first-child { top: 18px; }
.nav-toggle span:last-child  { top: 26px; }
.nav-toggle[aria-expanded="true"] span:first-child { top: 22px; transform: rotate(45deg); }
.nav-toggle[aria-expanded="true"] span:last-child  { top: 22px; transform: rotate(-45deg); }

/* =========================================================
   HERO
   ========================================================= */
.hero {
  position: relative;
  padding-top: calc(var(--header-h) + clamp(40px, 8vh, 90px));
  padding-bottom: clamp(60px, 10vh, 130px);
  overflow: hidden;
  isolation: isolate;
}

.hero-glow {
  position: absolute;
  z-index: -2;
  width: min(760px, 90vw);
  aspect-ratio: 1;
  right: -10%;
  top: -18%;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 50%, rgba(215, 154, 91, .32), rgba(215, 154, 91, 0) 62%);
  filter: blur(10px);
  animation: drift 18s ease-in-out infinite alternate;
}
.hero-grid-lines {
  position: absolute;
  inset: 0;
  z-index: -1;
  background-image:
    linear-gradient(to right, rgba(43, 32, 24, .045) 1px, transparent 1px);
  background-size: min(12.5%, 140px) 100%;
  mask-image: linear-gradient(to bottom, transparent, #000 25%, #000 70%, transparent);
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 25%, #000 70%, transparent);
  pointer-events: none;
}

@keyframes drift {
  from { transform: translate3d(0, 0, 0) scale(1); }
  to   { transform: translate3d(-40px, 30px, 0) scale(1.08); }
}

.hero-inner {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, .95fr);
  align-items: center;
  gap: clamp(30px, 5vw, 70px);
}

.hero-title {
  font-size: clamp(2.6rem, 7.4vw, 5.1rem);
  line-height: 1.12;
  letter-spacing: .02em;
  margin: 22px 0 26px;
}
.hero-title span { display: block; }

.hero-lead {
  max-width: 34em;
  color: var(--ink-soft);
  font-size: clamp(.95rem, 1.4vw, 1.03rem);
  line-height: 2.1;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 38px;
}

.hero-facts {
  display: flex;
  flex-wrap: wrap;
  gap: clamp(24px, 4vw, 46px);
  margin-top: 54px;
  padding-top: 26px;
  border-top: 1px solid var(--line);
}
.hero-facts dt { font-size: 10.5px; letter-spacing: .18em; text-transform: uppercase; color: var(--muted); }
.hero-facts dd { font-family: var(--font-serif); font-size: 16px; margin-top: 4px; }

/* ---- hero art : CSS coffee cup ---- */
.hero-art {
  position: relative;
  display: grid;
  place-items: center;
  min-height: clamp(320px, 42vw, 460px);
}
.disc {
  position: absolute;
  width: min(400px, 78%);
  aspect-ratio: 1;
  border-radius: 50%;
  background:
    radial-gradient(circle at 32% 28%, #3c2c20, #241a12 70%);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .07), var(--shadow-lg);
}
.disc::after {
  content: "";
  position: absolute;
  inset: 14%;
  border-radius: 50%;
  border: 1px dashed rgba(247, 243, 238, .18);
}
.cup {
  position: relative;
  transform: translateY(14px);
  filter: drop-shadow(0 26px 26px rgba(43, 32, 24, .3));
}
.cup-body {
  position: relative;
  width: clamp(150px, 20vw, 190px);
  height: clamp(120px, 16vw, 152px);
  background: linear-gradient(160deg, #fffdfa, #ecdfd0 62%, #d8c6b2);
  border-radius: 10px 10px 60px 60px / 12px 12px 74px 74px;
  overflow: hidden;
}
.cup-body::after {
  content: "";
  position: absolute;
  left: 16%; top: 8%;
  width: 22%; height: 80%;
  background: linear-gradient(to right, rgba(255, 255, 255, .8), rgba(255, 255, 255, 0));
  border-radius: 50%;
}
.cup-surface {
  position: absolute;
  inset: 0 0 auto 0;
  height: 14px;
  background: linear-gradient(90deg, #5a3a24, #7b4d2e 40%, #4a2f1c);
}
.cup-handle {
  position: absolute;
  right: -30px; top: 26px;
  width: 44px; height: 52px;
  border: 11px solid #f2e8dc;
  border-left: 0;
  border-radius: 0 40px 40px 0;
  box-shadow: inset -2px 0 0 rgba(180, 155, 130, .5);
}
.saucer {
  position: absolute;
  left: 50%; bottom: -22px;
  transform: translateX(-50%);
  width: clamp(200px, 27vw, 250px);
  height: 22px;
  border-radius: 50%;
  background: linear-gradient(180deg, #fffdfa, #ddd0c0);
  box-shadow: 0 10px 18px -10px rgba(43, 32, 24, .55);
}
.saucer::before {
  content: "";
  position: absolute;
  left: 50%; top: 6px;
  transform: translateX(-50%);
  width: 55%; height: 5px;
  border-radius: 50%;
  background: rgba(43, 32, 24, .12);
}

.steam {
  position: absolute;
  top: calc(50% - clamp(160px, 21vw, 200px));
  display: flex;
  gap: 16px;
  filter: blur(6px);
}
.steam span {
  width: 8px;
  height: clamp(52px, 7vw, 74px);
  border-radius: 999px;
  background: linear-gradient(to top, rgba(255, 253, 250, 0), rgba(255, 253, 250, .85));
  opacity: 0;
  animation: steam 4.6s var(--ease) infinite;
}
.steam span:nth-child(2) { animation-delay: .9s; height: clamp(64px, 8.5vw, 92px); }
.steam span:nth-child(3) { animation-delay: 1.8s; }

@keyframes steam {
  0%   { opacity: 0; transform: translateY(16px) scaleY(.6); }
  35%  { opacity: .9; }
  100% { opacity: 0; transform: translateY(-52px) scaleY(1.25); }
}

.hero-badge {
  position: absolute;
  right: 4%;
  bottom: 12%;
  width: 88px; height: 88px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--amber);
  color: #fff;
  font-family: var(--font-serif);
  font-size: 13px;
  letter-spacing: .16em;
  writing-mode: vertical-rl;
  text-orientation: upright;
  box-shadow: var(--shadow);
  animation: float 6s ease-in-out infinite;
}
@keyframes float {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-10px); }
}

.scroll-hint {
  position: absolute;
  left: 50%; bottom: 22px;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  font-size: 9.5px;
  letter-spacing: .3em;
  color: var(--muted);
}
.scroll-hint-line {
  width: 1px; height: 46px;
  background: linear-gradient(to bottom, transparent, var(--muted));
  animation: scrollLine 2.4s var(--ease) infinite;
}
@keyframes scrollLine {
  0%   { transform: scaleY(0); transform-origin: top; }
  50%  { transform: scaleY(1); transform-origin: top; }
  51%  { transform-origin: bottom; }
  100% { transform: scaleY(0); transform-origin: bottom; }
}

/* =========================================================
   MARQUEE
   ========================================================= */
.marquee {
  border-block: 1px solid var(--line);
  background: var(--cream-deep);
  padding-block: 18px;
  overflow: hidden;
}
.marquee-track {
  display: flex;
  align-items: center;
  gap: 30px;
  width: max-content;
  animation: marquee 26s linear infinite;
}
.marquee-track span {
  font-family: var(--font-serif);
  font-size: clamp(.95rem, 1.8vw, 1.15rem);
  letter-spacing: .12em;
  color: var(--ink-soft);
  white-space: nowrap;
}
.marquee-track span:nth-child(even) { color: var(--amber); font-family: var(--font-sans); }
@keyframes marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

/* =========================================================
   SECTIONS
   ========================================================= */
.section { padding: clamp(76px, 12vh, 140px) 0; scroll-margin-top: var(--header-h); }
.section-alt { background: var(--cream-deep); }

.section-head { max-width: 44em; margin-bottom: clamp(42px, 6vw, 68px); }
.section-title { font-size: clamp(1.8rem, 4.4vw, 3.1rem); margin: 18px 0 20px; }
.section-lead { color: var(--ink-soft); }

/* ---------- features ---------- */
.feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
}
.feature {
  background: var(--cream);
  padding: clamp(30px, 3.6vw, 44px);
  transition: background .5s var(--ease);
}
.feature:hover { background: #fffefc; }
.feature-num {
  display: block;
  font-family: var(--font-sans);
  font-size: 12px;
  letter-spacing: .2em;
  color: var(--amber);
  margin-bottom: 22px;
}
.feature h3 { font-size: 1.2rem; margin-bottom: 14px; }
.feature p { color: var(--ink-soft); font-size: .92rem; line-height: 2; }

.quote {
  margin: clamp(54px, 8vw, 90px) 0 0;
  padding-left: clamp(20px, 3vw, 34px);
  border-left: 2px solid var(--amber);
  max-width: 46em;
}
.quote p {
  font-family: var(--font-serif);
  font-size: clamp(1.15rem, 2.6vw, 1.7rem);
  line-height: 1.9;
}
.quote cite {
  display: block;
  margin-top: 16px;
  font-style: normal;
  font-size: 12.5px;
  letter-spacing: .14em;
  color: var(--muted);
}

/* ---------- menu ---------- */
.menu-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 34px;
}
.tab {
  padding: 9px 20px;
  border-radius: 999px;
  border: 1px solid var(--line);
  font-size: 13px;
  letter-spacing: .06em;
  color: var(--ink-soft);
  background: rgba(255, 255, 255, .5);
  transition: all .3s var(--ease);
}
.tab:hover { border-color: var(--muted); color: var(--ink); }
.tab.is-active { background: var(--espresso); border-color: var(--espresso); color: var(--cream); }

.menu-list {
  border-top: 1px solid var(--line);
}
.menu-item {
  display: flex;
  align-items: baseline;
  gap: 24px;
  padding: 26px 4px;
  border-bottom: 1px solid var(--line);
  transition: opacity .45s var(--ease), transform .45s var(--ease);
}
.menu-item.is-hidden { display: none; }
.menu-main { flex: 1; min-width: 0; }
.menu-main h3 {
  font-size: 1.15rem;
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
.menu-main p { color: var(--muted); font-size: .88rem; margin-top: 6px; }
.menu-price {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  white-space: nowrap;
  color: var(--ink);
}
.tag {
  font-family: var(--font-sans);
  font-size: 10px;
  letter-spacing: .12em;
  padding: 3px 9px;
  border-radius: 999px;
  background: var(--amber-tint);
  color: var(--amber);
  transform: translateY(-1px);
}
.menu-note { margin-top: 26px; font-size: 12.5px; color: var(--muted); }

/* ---------- space ---------- */
.space-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-auto-rows: clamp(150px, 20vw, 240px);
  gap: 16px;
}
.space-tile {
  position: relative;
  margin: 0;
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  align-items: flex-end;
  padding: 20px;
  box-shadow: var(--shadow-sm);
  transition: transform .6s var(--ease), box-shadow .6s var(--ease);
}
.space-tile::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(36, 28, 22, .55), transparent 55%);
}
.space-tile:hover { transform: translateY(-6px); box-shadow: var(--shadow); }
.tile-label {
  position: relative;
  z-index: 1;
  color: #fff;
  font-size: 12.5px;
  letter-spacing: .14em;
  text-shadow: 0 1px 8px rgba(0, 0, 0, .4);
}
.tile-a {
  grid-column: span 2;
  grid-row: span 2;
  background: linear-gradient(150deg, #6b4a30, #33231a 60%, #1d1510);
}
.tile-a::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(115deg, rgba(255, 255, 255, .05) 0 2px, transparent 2px 22px),
    radial-gradient(ellipse at 70% 30%, rgba(215, 154, 91, .35), transparent 60%);
}
.tile-b {
  grid-column: span 2;
  background: linear-gradient(160deg, #8a6a4c, #4a3323);
}
.tile-b::before {
  content: "";
  position: absolute;
  inset: 12% 18%;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 35%, #d79a5b, #7a4f2c 55%, #2b1d14);
  box-shadow: inset 0 0 30px rgba(0, 0, 0, .6);
}
.tile-c {
  background: linear-gradient(170deg, #cfd8d3, #7f9186 70%, #55655c);
}
.tile-c::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(to bottom right, rgba(255, 255, 255, .55) 0 30%, transparent 30%),
    radial-gradient(circle at 25% 20%, rgba(255, 255, 255, .5), transparent 45%);
}
.tile-d {
  background: linear-gradient(160deg, #2f2a3a, #171420);
}
.tile-d::before {
  content: "";
  position: absolute;
  left: 50%; top: 34%;
  width: 46px; height: 46px;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: radial-gradient(circle, #ffd9a0, rgba(255, 200, 130, 0) 70%);
  box-shadow: 0 0 60px 20px rgba(255, 200, 130, .28);
}

.amenities {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 34px;
}
.amenities li {
  font-size: 12.5px;
  letter-spacing: .05em;
  color: var(--ink-soft);
  padding: 8px 16px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 255, 255, .6);
}

/* ---------- shop ---------- */
.shop-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, .95fr);
  gap: clamp(34px, 6vw, 76px);
  align-items: start;
}
.info-list { margin-top: 34px; border-top: 1px solid var(--line); }
.info-list > div {
  display: grid;
  grid-template-columns: 6.5em 1fr;
  gap: 18px;
  padding: 16px 0;
  border-bottom: 1px solid var(--line);
}
.info-list dt { font-size: 12.5px; letter-spacing: .12em; color: var(--muted); }
.info-list dd { font-size: .95rem; }
.info-list a { border-bottom: 1px solid var(--amber); }

.shop-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 34px; }
.notice {
  margin-top: 26px;
  font-size: 12.5px;
  line-height: 2;
  color: var(--muted);
  padding: 18px 20px;
  background: rgba(255, 255, 255, .55);
  border-left: 2px solid var(--amber);
  border-radius: 0 10px 10px 0;
}

/* --- stylised map --- */
.shop-map {
  position: relative;
  aspect-ratio: 4 / 3.4;
  border-radius: var(--radius);
  overflow: hidden;
  background: #eae3d9;
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
}
.map-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(43, 32, 24, .05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(43, 32, 24, .05) 1px, transparent 1px);
  background-size: 34px 34px;
}
.road { position: absolute; background: #fffdfa; box-shadow: 0 0 0 1px var(--line); }
.road-h  { left: 0; right: 0; top: 46%; height: 30px; }
.road-h2 { left: 0; right: 0; top: 12%; height: 16px; opacity: .8; }
.road-v  { top: 0; bottom: 0; left: 30%; width: 26px; }
.river {
  position: absolute;
  left: 0; right: 0; bottom: 0;
  height: 18%;
  background: linear-gradient(to bottom, #b9cfd6, #9dbac4);
  opacity: .75;
}
.park {
  position: absolute;
  right: 8%; top: 58%;
  width: 26%; height: 26%;
  border-radius: 30% 70% 55% 45%;
  background: #b9cba9;
  opacity: .8;
}
.station {
  position: absolute;
  left: 30%; top: 12%;
  transform: translate(-50%, -50%);
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 11px;
  letter-spacing: .06em;
  color: var(--ink-soft);
  background: rgba(255, 253, 250, .92);
  padding: 5px 11px;
  border-radius: 999px;
  box-shadow: var(--shadow-sm);
  white-space: nowrap;
}
.station-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: #4b7fbf;
}
.route {
  position: absolute;
  left: 30%; top: 46%;
  width: 0; height: 0;
}
.pin {
  position: absolute;
  left: 62%; top: 30%;
  transform: translate(-50%, -100%);
  display: grid;
  place-items: center;
}
.pin-head {
  display: grid;
  place-items: center;
  padding: 8px 14px;
  border-radius: 999px;
  background: var(--espresso);
  color: var(--cream);
  font-family: var(--font-serif);
  font-size: 12.5px;
  letter-spacing: .12em;
  box-shadow: var(--shadow);
}
.pin-stem {
  width: 2px; height: 26px;
  background: var(--espresso);
  position: relative;
}
.pin-stem::after {
  content: "";
  position: absolute;
  left: 50%; bottom: -4px;
  transform: translateX(-50%);
  width: 12px; height: 12px;
  border-radius: 50%;
  background: rgba(185, 118, 63, .35);
  animation: pulse 2.6s var(--ease) infinite;
}
@keyframes pulse {
  0%   { transform: translateX(-50%) scale(.6); opacity: .9; }
  100% { transform: translateX(-50%) scale(2.4); opacity: 0; }
}

/* =========================================================
   FOOTER
   ========================================================= */
.site-footer {
  background: var(--espresso);
  color: rgba(247, 243, 238, .82);
  padding-top: clamp(56px, 8vw, 88px);
}
.footer-inner {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 34px;
  padding-bottom: 46px;
  border-bottom: 1px solid rgba(247, 243, 238, .14);
}
.footer-brand .brand-name { font-size: 22px; color: var(--cream); letter-spacing: .16em; }
.footer-brand p { margin-top: 12px; font-size: 12.5px; letter-spacing: .1em; color: rgba(247, 243, 238, .55); }
.footer-nav { display: flex; flex-wrap: wrap; gap: 26px; align-items: center; }
.footer-nav a, .footer-social a {
  font-size: 13px;
  letter-spacing: .08em;
  color: rgba(247, 243, 238, .78);
  transition: color .3s var(--ease);
}
.footer-nav a:hover, .footer-social a:hover { color: var(--amber-soft); }
.footer-social { display: flex; gap: 22px; }

.footer-bottom {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 10px;
  padding-block: 28px 34px;
  font-size: 11.5px;
  letter-spacing: .06em;
  color: rgba(247, 243, 238, .45);
}

/* =========================================================
   REVEAL ANIMATION
   ========================================================= */
.reveal {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity .9s var(--ease), transform .9s var(--ease);
  transition-delay: var(--d, 0s);
}
.reveal.is-visible { opacity: 1; transform: none; }

/* =========================================================
   RESPONSIVE
   ========================================================= */
@media (max-width: 980px) {
  .hero-inner { grid-template-columns: 1fr; }
  .hero-art { order: -1; min-height: 300px; }
  .shop-grid { grid-template-columns: 1fr; }
  .space-grid { grid-template-columns: repeat(2, 1fr); }
  .tile-a { grid-column: span 2; grid-row: span 1; }
  .tile-b { grid-column: span 2; }
}

@media (max-width: 760px) {
  :root { --header-h: 66px; }

  .nav {
    position: fixed;
    inset: var(--header-h) 0 auto 0;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    padding: 10px clamp(20px, 5vw, 48px) 30px;
    background: rgba(247, 243, 238, .97);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    border-bottom: 1px solid var(--line);
    box-shadow: var(--shadow);
    transform: translateY(-12px);
    opacity: 0;
    visibility: hidden;
    transition: opacity .3s var(--ease), transform .4s var(--ease), visibility .3s;
  }
  .nav.is-open { opacity: 1; visibility: visible; transform: none; }
  .nav ul { flex-direction: column; gap: 0; }
  .nav ul li { border-bottom: 1px solid var(--line); }
  .nav a:not(.btn) { display: block; padding: 18px 4px; font-size: 15px; }
  .nav a:not(.btn)::after { display: none; }
  .nav-cta { margin-top: 22px; justify-content: center; }

  .nav-toggle { display: block; }

  .hero-facts { gap: 22px 34px; }
  .menu-item { flex-direction: column; gap: 6px; align-items: flex-start; }
  .menu-price { align-self: flex-end; }
  .info-list > div { grid-template-columns: 1fr; gap: 4px; }
  .scroll-hint { display: none; }
}

@media (max-width: 420px) {
  .space-grid { grid-template-columns: 1fr; }
  .tile-a, .tile-b { grid-column: span 1; }
}

/* =========================================================
   MOTION / PRINT
   ========================================================= */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: .001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .001ms !important;
  }
  .reveal { opacity: 1; transform: none; }
}

@media print {
  .site-header, .marquee, .scroll-hint, .hero-art, .map-grid { display: none; }
  body { background: #fff; }
}
