{"content":"/* =========================================================
   珈琲 灯里 — interactions
   ========================================================= */
(function () {
  'use strict';

  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ---------- 1. header: scrolled state ---------- */
  const header = document.querySelector('.site-header');
  const onScroll = () => {
    header.classList.toggle('is-scrolled', window.scrollY > 20);
  };
  onScroll();
  window.addEventListener('scroll', onScroll, { passive: true });

  /* ---------- 2. mobile navigation ---------- */
  const nav = document.getElementById('nav');
  const navToggle = document.getElementById('navToggle');

  const setNav = (open) => {
    nav.classList.toggle('is-open', open);
    navToggle.setAttribute('aria-expanded', String(open));
    navToggle.setAttribute('aria-label', open ? 'メニューを閉じる' : 'メニューを開く');
  };

  navToggle.addEventListener('click', () => {
    setNav(!nav.classList.contains('is-open'));
  });

  // close after tapping a link
  nav.addEventListener('click', (e) => {
    if (e.target.closest('a')) setNav(false);
  });

  // close on outside click / escape
  document.addEventListener('click', (e) => {
    if (!nav.classList.contains('is-open')) return;
    if (e.target.closest('#nav') || e.target.closest('#navToggle')) return;
    setNav(false);
  });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') setNav(false);
  });

  // reset when resizing back to desktop
  window.addEventListener('resize', () => {
    if (window.innerWidth > 760) setNav(false);
  });

  /* ---------- 3. scroll reveal ---------- */
  const revealTargets = document.querySelectorAll('.reveal');

  if (reduceMotion || !('IntersectionObserver' in window)) {
    revealTargets.forEach((el) => el.classList.add('is-visible'));
  } else {
    const io = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        entry.target.classList.add('is-visible');
        io.unobserve(entry.target);
      });
    }, { rootMargin: '0px 0px -12% 0px', threshold: 0.12 });

    revealTargets.forEach((el) => io.observe(el));
  }

  /* ---------- 4. menu filter ---------- */
  const tabs = document.querySelectorAll('.tab');
  const items = document.querySelectorAll('.menu-item');

  tabs.forEach((tab) => {
    tab.addEventListener('click', () => {
      const filter = tab.dataset.filter;

      tabs.forEach((t) => {
        const active = t === tab;
        t.classList.toggle('is-active', active);
        t.setAttribute('aria-selected', String(active));
      });

      items.forEach((item) => {
        const show = filter === 'all' || item.dataset.cat === filter;
        item.classList.toggle('is-hidden', !show);
      });
    });
  });

  /* ---------- 5. footer year ---------- */
  const year = document.getElementById('year');
  if (year) year.textContent = String(new Date().getFullYear());

  /* ---------- 6. smooth anchor offset fallback ---------- */
  // CSS `scroll-margin-top` handles most browsers; this covers old Safari.
  document.querySelectorAll('a[href^="#"]').forEach((link) => {
    link.addEventListener('click', (e) => {
      const id = link.getAttribute('href');
      if (id === '#' || id.length < 2) return;
      const target = document.querySelector(id);
      if (!target) return;

      e.preventDefault();
      const top = target.getBoundingClientRect().top + window.scrollY
        - (parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--header-h')) || 76);
      window.scrollTo({ top, behavior: reduceMotion ? 'auto' : 'smooth' });
      history.replaceState(null, '', id);
    });
  });
})();
