from html.parser import HTMLParser
VOID={'meta','link','br','hr','img','input','source','path','circle','area','col','embed','track','wbr','use'}
class P(HTMLParser):
    def __init__(s):
        super().__init__(); s.stack=[]; s.err=[]
    def handle_starttag(s,t,a):
        if t not in VOID: s.stack.append((t,s.getpos()))
    def handle_endtag(s,t):
        if t in VOID: return
        if not s.stack: s.err.append(f"stray </{t}> at {s.getpos()}"); return
        if s.stack[-1][0]!=t:
            s.err.append(f"mismatch </{t}> at {s.getpos()}, open <{s.stack[-1][0]}> from {s.stack[-1][1]}")
            for i in range(len(s.stack)-1,-1,-1):
                if s.stack[i][0]==t:
                    del s.stack[i:]; return
        else: s.stack.pop()
p=P(); p.feed(open('index.html',encoding='utf-8').read())
print("unclosed:", [(t,pos) for t,pos in p.stack])
print("errors:", p.err or "none")
EOF"}

