/* ---------- page head (menu.html) ---------- */
.page-head {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  padding-top: calc(var(--header-h) + clamp(48px, 9vh, 100px));
  padding-bottom: clamp(38px, 6vh, 60px);
  background: linear-gradient(180deg, #f4ece2 0%, #f7f3ee 78%);
}
.page-title {
  font-size: clamp(2.1rem, 6vw, 3.9rem);
  line-height: 1.2;
  letter-spacing: .03em;
  margin: 20px 0 24px;
}
.page-lead { max-width: 40em; color: var(--ink-soft); }
.page-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 9px;
  margin-top: 26px;
  font-size: 12px;
  letter-spacing: .12em;
  color: var(--ink-soft);
}
/* メニューページでは下端をフェードさせない */
.page-vignette {
  inset: 0;
  background: radial-gradient(120% 90% at 50% 28%, transparent 52%, rgba(43, 32, 24, .07) 100%);
}

/* ---------- カテゴリー内ナビ ---------- */
.subnav {
  position: sticky;
  top: var(--header-h);
  z-index: 60;
  background: rgba(247, 243, 238, .86);
  backdrop-filter: blur(14px) saturate(1.4);
  -webkit-backdrop-filter: blur(14px) saturate(1.4);
  border-bottom: 1px solid var(--line);
}
.subnav-inner {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  padding-block: 12px;
  scrollbar-width: none;
}
.subnav-inner::-webkit-scrollbar { display: none; }
.subnav a {
  flex: 0 0 auto;
  padding: 8px 18px;
  border-radius: 999px;
  border: 1px solid transparent;
  font-size: 13px;
  letter-spacing: .06em;
  color: var(--ink-soft);
  white-space: nowrap;
  transition: background .3s var(--ease), color .3s var(--ease), border-color .3s var(--ease);
}
.subnav a:hover { border-color: var(--line); color: var(--ink); }
.subnav a.is-active { background: var(--espresso); color: var(--cream); border-color: var(--espresso); }

/* ---------- notes / CTA (menu.html) ---------- */
.notes-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 260px), 1fr));
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
}
.note-card {
  background: var(--cream);
  padding: clamp(26px, 3vw, 36px);
}
.note-card h3 { font-size: 1.02rem; margin-bottom: 12px; }
.note-card p { color: var(--ink-soft); font-size: .88rem; line-height: 2; }

.menu-cta {
  display: flex;
  flex-wrap: wrap;
