{"newString":"  /* ---------- 6. smooth anchor offset fallback ---------- */
  // CSS `scroll-margin-top` handles most browsers; this covers old Safari.
  const subnav = document.querySelector('.subnav');

  document.querySelectorAll('a[href^="#"]').forEach((link) => {
    link.addEventListener('click', (e) => {
      const id = link.getAttribute('href');
      if (id === '#' || id.length < 2) return;
      const target = document.querySelector(id);
      if (!target) return;

      e.preventDefault();
      const headerH = parseFloat(
        getComputedStyle(document.documentElement).getPropertyValue('--header-h')
      ) || 76;
      // メニューページでは追従ナビのぶんも足して、見出しが隠れないようにする
      const extra = subnav ? subnav.offsetHeight : 0;
      const top = target.getBoundingClientRect().top + window.scrollY - headerH - extra;

      window.scrollTo({ top, behavior: reduceMotion ? 'auto' : 'smooth' });
      history.replaceState(null, '', id);
    });
  });
})();","oldString":"  /* ---------- 6. smooth anchor offset fallback ---------- */
